import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.DXGs2oJ2.js";const i=JSON.parse('{"title":"第 22 章　典型场景实践","description":"","frontmatter":{},"headers":[],"relativePath":"06-case-study/22-典型场景实践.md","filePath":"06-case-study/22-典型场景实践.md","lastUpdated":1793361704000}'),n={name:"06-case-study/22-典型场景实践.md"};function s(u,t,p,d,q,h){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-22-章-典型场景实践" tabindex="-1">第 22 章　典型场景实践 <a class="header-anchor" href="#第-22-章-典型场景实践" aria-label="Permalink to &quot;第 22 章　典型场景实践&quot;">​</a></h1><p>前面五章建立的是通用方法：责任域怎么划分、写入与检索怎么做、治理怎么落地、选型怎么判断。但方法要落到场景里才有意义，而场景之间的差异不在技术栈，在<strong>失效后果的严重程度</strong>与<strong>可接受的召回错误率</strong>。</p><p>一个个人助理记错用户口味，用户会纠正，成本是一句抱怨。一个医疗随访系统记错过敏史，成本是一次医疗事故。两者用的是同一套机制，但配置、验收标准与投入完全不同。把这些差异写清楚，比再给一套通用最佳实践更有用。</p><p>本章选五个场景，每个按四段展开：业务约束、记忆设计、失效点、验收方法。五个场景覆盖了从低风险高容忍到高风险低容忍的完整区间，也覆盖了中文场景的特殊问题。</p><h2 id="_22-1-个人助理-偏好漂移与过度概括" tabindex="-1">22.1 个人助理：偏好漂移与过度概括 <a class="header-anchor" href="#_22-1-个人助理-偏好漂移与过度概括" aria-label="Permalink to &quot;22.1 个人助理：偏好漂移与过度概括&quot;">​</a></h2><h3 id="_22-1-1-业务约束" tabindex="-1">22.1.1 业务约束 <a class="header-anchor" href="#_22-1-1-业务约束" aria-label="Permalink to &quot;22.1.1 业务约束&quot;">​</a></h3><p>个人助理的记忆需求有三个特征：写入频率低（一天几条）、读取频率高（每轮对话都要用）、错误容忍度高（用户会纠正）。</p><p>约束的关键在于<strong>用户是唯一的裁判</strong>。系统不需要向第三方证明什么，只需要让用户感觉&quot;它懂我&quot;。这意味着审计链、级联删除这些能力在这里的优先级远低于召回准确率与响应速度。</p><h3 id="_22-1-2-记忆设计" tabindex="-1">22.1.2 记忆设计 <a class="header-anchor" href="#_22-1-2-记忆设计" aria-label="Permalink to &quot;22.1.2 记忆设计&quot;">​</a></h3><p>核心是<strong>分层画像</strong>。把记忆分成三层：稳定身份（职业、语言习惯、长期偏好）、偏好与约束（饮食禁忌、沟通风格）、当前情境（最近在做什么项目、这周的目标）。</p><p>分层的价值在于更新频率不同。稳定身份几乎不变，当前情境每周都变。如果混在一起，每次情境更新都会污染身份层。</p><p>第二个设计是<strong>来源标注</strong>。区分&quot;用户明确说的&quot;与&quot;系统推断的&quot;。用户说&quot;我不吃香菜&quot;是明确的；系统从三次点餐记录推断&quot;偏好清淡&quot;是推断的。两者在召回时的权重应当不同。</p><h3 id="_22-1-3-失效点-过度概括" tabindex="-1">22.1.3 失效点：过度概括 <a class="header-anchor" href="#_22-1-3-失效点-过度概括" aria-label="Permalink to &quot;22.1.3 失效点：过度概括&quot;">​</a></h3><p>最常见的失效不是记错，而是<strong>从具体推一般时推过头</strong>。</p><p>用户说过三次&quot;少放辣&quot;，系统推断出&quot;不吃辣&quot;并写入偏好层。下次用户点麻辣火锅时，助理推荐了清汤锅底，用户困惑。</p><p>这个失效的机制是：单次陈述被提升为稳定属性，而提升过程没有置信度衰减。正确做法是把推断结果标为低置信度、放在情境层而非偏好层、并在每次使用时允许被推翻。</p><p>第二个失效点是<strong>偏好漂移未及时反映</strong>。用户三个月前喜欢深色模式，现在改用浅色。如果旧记忆没有被新记忆压制，系统会持续推荐深色。这要求检索时必须考虑时间信号，而不只是语义相似度。</p><h3 id="_22-1-4-验收方法" tabindex="-1">22.1.4 验收方法 <a class="header-anchor" href="#_22-1-4-验收方法" aria-label="Permalink to &quot;22.1.4 验收方法&quot;">​</a></h3><p>三个可执行的检查。</p><p><strong>分层可展示性</strong>：系统能否向用户展示&quot;我记住了什么&quot;并按层组织？如果只能给一个平铺列表，用户无法判断哪条是身份、哪条是临时情境。</p><p><strong>推翻成本</strong>：用户说&quot;不对，我现在喜欢浅色&quot;之后，需要几次交互才能让系统改正？超过一次就说明写入路径缺少冲突消解。</p><p><strong>过度概括率</strong>：抽样 50 条系统推断的记忆，人工判断有多少条是&quot;从一次陈述推出的稳定属性&quot;。超过 20% 说明推断过于激进。</p><h2 id="_22-2-企业客服与-crm-旧事实压过新事实" tabindex="-1">22.2 企业客服与 CRM：旧事实压过新事实 <a class="header-anchor" href="#_22-2-企业客服与-crm-旧事实压过新事实" aria-label="Permalink to &quot;22.2 企业客服与 CRM：旧事实压过新事实&quot;">​</a></h2><h3 id="_22-2-1-业务约束" tabindex="-1">22.2.1 业务约束 <a class="header-anchor" href="#_22-2-1-业务约束" aria-label="Permalink to &quot;22.2.1 业务约束&quot;">​</a></h3><p>客服场景的记忆有三个特征：写入频率高（每次交互都产生记录）、读取必须实时（用户等待中）、错误后果中等（影响满意度但不直接违法）。</p><p>关键约束是<strong>多来源</strong>。同一个客户的信息来自工单系统、通话记录、邮件、订单库，四个来源的更新时间不同，且可能互相矛盾。</p><h3 id="_22-2-2-记忆设计" tabindex="-1">22.2.2 记忆设计 <a class="header-anchor" href="#_22-2-2-记忆设计" aria-label="Permalink to &quot;22.2.2 记忆设计&quot;">​</a></h3><p>核心是<strong>双时间轴 + 来源优先级</strong>。</p><p>双时间轴区分&quot;事实何时发生&quot;与&quot;系统何时获知&quot;。一条&quot;客户已升级到企业版&quot;的记录，发生时间是上周，但系统可能是今天才知道。如果只记录写入时间，系统会误判这条信息的新鲜度。</p><p>来源优先级解决矛盾。订单库的状态优先于通话记录里的口头承诺；正式工单的结论优先于聊天中的猜测。这个优先级需要显式配置，不能靠模型判断。</p><p>第二个设计是<strong>冲突显式化</strong>。当两个来源给出矛盾信息时，不要静默选一个，而是把矛盾标记出来，让检索结果带上&quot;存在冲突&quot;的标记。人工客服看到标记后会主动确认，而静默选择会让错误持续。</p><h3 id="_22-2-3-失效点-旧事实持续生效" tabindex="-1">22.2.3 失效点：旧事实持续生效 <a class="header-anchor" href="#_22-2-3-失效点-旧事实持续生效" aria-label="Permalink to &quot;22.2.3 失效点：旧事实持续生效&quot;">​</a></h3><p>最典型的失效是：客户三个月前投诉过物流慢，系统把&quot;对物流敏感&quot;写进画像。客户后来换了收货地址，物流问题解决了，但画像没更新。每次交互系统都主动提&quot;我们注意到您之前对物流有顾虑&quot;，客户觉得系统在翻旧账。</p><p>机制上，这是<strong>派生结论没有随源事实失效</strong>。源事实（那次投诉）已经不再有预测价值，但派生结论（物流敏感）独立存在且没有过期机制。</p><p>第二个失效点是<strong>跨会话的上下文污染</strong>。上一个客服会话里客户表达了不满情绪，这个情绪被写入记忆，下一次会话开始时系统带着&quot;这位客户可能不满&quot;的先验，导致语气过度谨慎。</p><h3 id="_22-2-4-验收方法" tabindex="-1">22.2.4 验收方法 <a class="header-anchor" href="#_22-2-4-验收方法" aria-label="Permalink to &quot;22.2.4 验收方法&quot;">​</a></h3><p><strong>时序正确率</strong>：构造 20 组&quot;新旧事实冲突&quot;的测试用例，看系统返回的是新事实还是旧事实。目标 90% 以上返回新事实。</p><p><strong>冲突可见率</strong>：故意注入矛盾的来源，看检索结果是否带冲突标记。目标 100% 可见。</p><p><strong>过期清理</strong>：统计超过 90 天未被引用且未被更新的记忆占比。超过 40% 说明缺少降级机制。</p><h2 id="_22-3-研发效能-agent-经验负迁移" tabindex="-1">22.3 研发效能 Agent：经验负迁移 <a class="header-anchor" href="#_22-3-研发效能-agent-经验负迁移" aria-label="Permalink to &quot;22.3 研发效能 Agent：经验负迁移&quot;">​</a></h2><h3 id="_22-3-1-业务约束" tabindex="-1">22.3.1 业务约束 <a class="header-anchor" href="#_22-3-1-业务约束" aria-label="Permalink to &quot;22.3.1 业务约束&quot;">​</a></h3><p>研发场景的记忆需求特殊：写入的是<strong>方法</strong>而非事实，读取发生在任务开始时，错误后果可能是引入 bug。</p><p>关键约束是<strong>经验有适用条件</strong>。&quot;这个项目里我们用 pnpm 而不是 npm&quot;是一条有效经验，但它只在特定项目成立。如果被无差别套用到另一个项目，会造成构建失败。</p><h3 id="_22-3-2-记忆设计" tabindex="-1">22.3.2 记忆设计 <a class="header-anchor" href="#_22-3-2-记忆设计" aria-label="Permalink to &quot;22.3.2 记忆设计&quot;">​</a></h3><p>核心是<strong>前置条件必填</strong>。保存一条可复用经验时，必须同时记录三件事：什么条件下适用（must）、什么条件下不适用（must_not）、典型环境是什么（typical_env）。</p><p>没有这三件事的&quot;经验&quot;实际上是&quot;建议&quot;，而建议的可靠性远低于经验。</p><p>第二个设计是<strong>召回时做前置条件校验</strong>。不是简单返回匹配的经验，而是判断当前环境是否满足 must、是否触发 must_not，只返回通过校验的条目，并给出未通过的原因。</p><p>Mnemosyne 的 <code>playbook_save</code> 把 <code>preconditions</code> 设为必填字段，<code>playbook_recall</code> 返回 <code>applicable</code> 与 <code>blocked_by</code>。这个设计的代价是写入时更麻烦——调用方必须想清楚适用条件，而这件事经常被跳过。</p><p>第三个设计是<strong>代码演进记忆</strong>。记录每次变更的意图、约束、影响面与被拒绝的方案。这类记忆的价值不在于&quot;当时改了什么&quot;，而在于&quot;当时为什么不那样改&quot;——后者在六个月后无人记得。</p><h3 id="_22-3-3-失效点-负迁移" tabindex="-1">22.3.3 失效点：负迁移 <a class="header-anchor" href="#_22-3-3-失效点-负迁移" aria-label="Permalink to &quot;22.3.3 失效点：负迁移&quot;">​</a></h3><p>最典型的失效是：某条经验在 A 项目有效，被套用到 B 项目造成事故。</p><p>具体形态：Agent 在 A 项目学到&quot;遇到类型错误先检查 tsconfig 的 strict 设置&quot;，这个经验被存入经验库且没有前置条件。在 B 项目里遇到类型错误时，Agent 直接去改 tsconfig，而 B 项目的真实问题是依赖版本冲突。改动 tsconfig 掩盖了症状，问题在两天后以更严重的形式爆发。</p><p>机制上，这是<strong>经验被当作通用规则</strong>。前置条件缺失让召回变成了关键词匹配，而关键词匹配无法区分&quot;相似的问题&quot;与&quot;相同的问题&quot;。</p><p>第二个失效点是<strong>经验库变成教条库</strong>。随着经验积累，Agent 越来越依赖历史做法，对新情况的探索减少。表现为：遇到新问题时，Agent 反复尝试历史方案而不是分析当前问题。</p><h3 id="_22-3-4-验收方法" tabindex="-1">22.3.4 验收方法 <a class="header-anchor" href="#_22-3-4-验收方法" aria-label="Permalink to &quot;22.3.4 验收方法&quot;">​</a></h3><p><strong>前置条件覆盖率</strong>：统计经验库中有完整 must / must_not / typical_env 的条目占比。目标 100%，低于 80% 说明写入纪律未落实。</p><p><strong>负迁移检出</strong>：构造 10 组&quot;经验不适用&quot;的场景，看 <code>playbook_recall</code> 是否正确返回 <code>blocked_by</code>。目标 100%。</p><p><strong>探索率</strong>：统计 Agent 在遇到新问题时使用历史方案与现场分析的比例。探索率持续下降说明经验库在压制探索。</p><h2 id="_22-4-合规敏感行业-删了但派生结论还在" tabindex="-1">22.4 合规敏感行业：删了但派生结论还在 <a class="header-anchor" href="#_22-4-合规敏感行业-删了但派生结论还在" aria-label="Permalink to &quot;22.4 合规敏感行业：删了但派生结论还在&quot;">​</a></h2><h3 id="_22-4-1-业务约束" tabindex="-1">22.4.1 业务约束 <a class="header-anchor" href="#_22-4-1-业务约束" aria-label="Permalink to &quot;22.4.1 业务约束&quot;">​</a></h3><p>医疗与金融场景的记忆有三个特征：写入需谨慎（每条都可能是证据）、读取需授权（越权读取是事故）、删除需可证（法定删除权）。</p><p>关键约束是<strong>没有任何一步可以&quot;大概对&quot;</strong>。审计方会追问细节，而细节层面的含糊会被认定为不合规。</p><h3 id="_22-4-2-记忆设计" tabindex="-1">22.4.2 记忆设计 <a class="header-anchor" href="#_22-4-2-记忆设计" aria-label="Permalink to &quot;22.4.2 记忆设计&quot;">​</a></h3><p>核心是<strong>四层删除语义 + 派生关系记录</strong>。</p><p>派生关系必须在写入时建立，而不是删除时推断。一条&quot;患者对布洛芬不过敏&quot;的记忆，可能已经生成了&quot;可用 NSAIDs&quot;的派生结论、被引用进了两次会诊摘要、影响了三条用药建议。这些关系如果不在写入时记录，删除时只能靠全文扫描，准确率无法保证。</p><p>第二个设计是<strong>删除预览</strong>。执行删除前，必须能看到受影响的派生条目、摘要、缓存清单，而不只是一个数量。决策者需要判断&quot;删掉这些是否可接受&quot;。</p><p>第三个设计是<strong>审计链的完整性</strong>。每次删除都要入链，记录谁在什么时间删了什么、影响了什么。这不是为了追责，而是为了在审查时能证明&quot;删除是按流程执行的&quot;。</p><h3 id="_22-4-3-失效点-派生结论残留" tabindex="-1">22.4.3 失效点：派生结论残留 <a class="header-anchor" href="#_22-4-3-失效点-派生结论残留" aria-label="Permalink to &quot;22.4.3 失效点：派生结论残留&quot;">​</a></h3><p>最典型的失效就是 13 章开头那个案例：源记录删了，摘要还在引用，策略还在用旧参数。</p><p>具体形态：患者行使删除权，要求清除&quot;收入水平&quot;相关记忆。运维执行删除，接口返回成功，检索确认查不到。三个月后合规抽查发现，该患者的会话摘要里仍有一句&quot;月收入约 2 万&quot;，依赖该记忆生成的随访策略仍在使用旧参数。</p><p>机制上，这是<strong>删除只做了第一层</strong>。四层语义中，源记录删除是最简单的一层，派生失效、缓存清除、摘要标陈旧都需要额外机制。</p><p>第二个失效点是<strong>导出副本与删除权冲突</strong>。为了保留审计证据，系统做过防删除导出。用户要求删除时，这份导出是否也删？如果保留，是否构成对删除权的违反？</p><h3 id="_22-4-4-验收方法" tabindex="-1">22.4.4 验收方法 <a class="header-anchor" href="#_22-4-4-验收方法" aria-label="Permalink to &quot;22.4.4 验收方法&quot;">​</a></h3><p><strong>级联完整性测试</strong>：删除一条有依赖的记忆，验证派生结论、缓存、摘要四个层次都被处理。目标 100%。</p><p><strong>预览准确率</strong>：对比预览列出的影响项与实际受影响项，目标 100% 一致。不一致说明派生关系记录不全。</p><p><strong>导出范围声明</strong>：每次删除处理记录中，必须明确列出&quot;本次删除覆盖的范围&quot;与&quot;范围之外保留的副本及理由&quot;。缺这一项，审查时会被追问。</p><h2 id="_22-5-中文为主的企业知识场景-专有名词召回失准" tabindex="-1">22.5 中文为主的企业知识场景：专有名词召回失准 <a class="header-anchor" href="#_22-5-中文为主的企业知识场景-专有名词召回失准" aria-label="Permalink to &quot;22.5 中文为主的企业知识场景：专有名词召回失准&quot;">​</a></h2><h3 id="_22-5-1-业务约束" tabindex="-1">22.5.1 业务约束 <a class="header-anchor" href="#_22-5-1-业务约束" aria-label="Permalink to &quot;22.5.1 业务约束&quot;">​</a></h3><p>中文场景的记忆需求有两个特殊点：分词没有空格边界，专有名词（产品型号、人名、项目代号）在嵌入空间中区分度低。</p><p>关键约束是<strong>关键词信号不能只做兜底</strong>。多数系统的设计是&quot;语义为主，词法兜底&quot;，但在中文专有名词场景，词法才是主力。</p><h3 id="_22-5-2-记忆设计" tabindex="-1">22.5.2 记忆设计 <a class="header-anchor" href="#_22-5-2-记忆设计" aria-label="Permalink to &quot;22.5.2 记忆设计&quot;">​</a></h3><p>核心是<strong>词法信号作为一等公民</strong>。</p><p>Bigram 分词是零依赖条件下最稳定的 n-gram 策略：把&quot;华为Mate60Pro&quot;切成二元组，既保留了&quot;Mate60&quot;这样的关键片段，又不需要词典。配合 FTS5 全文索引，可以在没有嵌入模型的情况下完成基础召回。</p><p>第二个设计是<strong>同义词词典</strong>。中文的近义表达（&quot;偏好&quot;/&quot;喜欢&quot;/&quot;习惯&quot;）在语义上接近，但在词法上完全不同。内置词典让词法检索能覆盖这些变体。</p><p>第三个设计是<strong>相对时间解析</strong>。&quot;上周三&quot;&quot;去年底&quot;&quot;这季度&quot;必须被解析为绝对日期，否则双时间轴直接失效，而双时间轴是冲突裁决的基础。</p><h3 id="_22-5-3-失效点-纯嵌入召回在型号上失准" tabindex="-1">22.5.3 失效点：纯嵌入召回在型号上失准 <a class="header-anchor" href="#_22-5-3-失效点-纯嵌入召回在型号上失准" aria-label="Permalink to &quot;22.5.3 失效点：纯嵌入召回在型号上失准&quot;">​</a></h3><p>最典型的失效是：用户问&quot;Mate60 的保修政策&quot;，系统返回了&quot;Mate50 的保修政策&quot;。</p><p>机制上，两个型号在嵌入空间中的距离很近（都是手机型号、都是华为产品、句子结构相似），但在业务上完全不同。语义相似度在这里给出的是错误信号。</p><p>第二个失效点是<strong>中文摘要的过度压缩</strong>。中文的信息密度高，摘要压缩时容易丢掉关键限定词（&quot;仅限&quot;、&quot;不包括&quot;、&quot;除…之外&quot;），导致语义反转。</p><h3 id="_22-5-4-验收方法" tabindex="-1">22.5.4 验收方法 <a class="header-anchor" href="#_22-5-4-验收方法" aria-label="Permalink to &quot;22.5.4 验收方法&quot;">​</a></h3><p><strong>专有名词召回率</strong>：构造 50 组&quot;型号/人名/代号&quot;查询，看 top-5 是否命中正确条目。目标 85% 以上，纯嵌入方案通常在 60% 左右。</p><p><strong>词法-语义对照实验</strong>：同一批查询分别用纯嵌入、纯词法、融合三种方式跑，比较命中率。这个实验能直接说明在特定语料上哪种信号更有效。</p><p><strong>时间解析正确率</strong>：抽样 50 条含相对时间表达的输入，看解析结果是否符合预期。</p><h2 id="_22-6-场景与能力的映射" tabindex="-1">22.6 场景与能力的映射 <a class="header-anchor" href="#_22-6-场景与能力的映射" aria-label="Permalink to &quot;22.6 场景与能力的映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>关键能力</th><th>主要风险</th><th>核心验收指标</th></tr></thead><tbody><tr><td>个人助理</td><td>分层画像、来源标注、时间信号</td><td>过度概括、偏好漂移</td><td>过度概括率 &lt; 20%</td></tr><tr><td>客服与 CRM</td><td>双时间轴、来源优先级、冲突显式化</td><td>旧事实压制新事实</td><td>时序正确率 &gt; 90%</td></tr><tr><td>研发效能</td><td>前置条件必填、召回校验、变更记忆</td><td>经验负迁移</td><td>前置条件覆盖率 100%</td></tr><tr><td>合规敏感</td><td>四层删除、派生关系、删除预览</td><td>派生结论残留</td><td>级联完整性 100%</td></tr><tr><td>中文知识</td><td>Bigram + FTS5、同义词、时间解析</td><td>专有名词失准</td><td>专名召回率 &gt; 85%</td></tr></tbody></table><p>表 22-1　五类场景的能力映射与验收指标</p><p>这张表最有用的地方是最后一列：每个场景都有一个可以用脚本验证的核心指标。没有这个指标的团队，实际上无法判断自己的记忆系统是否在工作。</p><h2 id="_22-7-本章小结" tabindex="-1">22.7 本章小结 <a class="header-anchor" href="#_22-7-本章小结" aria-label="Permalink to &quot;22.7 本章小结&quot;">​</a></h2><p>本章确立了三条判断。</p><p><strong>第一，场景之间的差异不在技术栈，在失效后果与可接受错误率。</strong> 个人助理能容忍 20% 的过度概括，医疗场景不能容忍任何派生结论残留。同一套机制在不同场景下的配置与验收标准完全不同，套用通用最佳实践会导致资源配置错位。</p><p><strong>第二，每个场景都有一个决定性的失效模式，而它通常不是&quot;记错&quot;。</strong> 个人助理的失效是过度概括，客服的失效是旧事实压制新事实，研发的失效是经验负迁移，合规的失效是派生结论残留，中文的失效是专有名词失准。五种失效对应五套不同机制，没有一个通用方案能同时防住。</p><p><strong>第三，验收必须落到可脚本化的指标。</strong> 过度概括率、时序正确率、前置条件覆盖率、级联完整性、专名召回率——五个指标都能用固定数据集验证。没有这类指标的团队，只能靠用户投诉发现问题，而用户投诉的滞后性在合规场景里是不可接受的。</p><p>本章是实践篇的最后一章。接下来的展望篇要处理的是这些场景共同面对的、目前无解的问题。</p><hr>',104)])])}const g=o(n,[["render",s]]);export{i as __pageData,g as default};
